# Bank zadań autorskich — partia 2: wiek XIX (dokończenie) i średniowiecze.
# B(tytuł, materiał, *zadania) — wiązka; T(typ, punkty, polecenie, odpowiedź, omówienie) — zadanie.
# Zasada dystraktorów: każda błędna odpowiedź pochodzi z tej samej epoki i kontekstu.
BANK = {}

BANK['xix-wiek'] = [
 B('Dwa obozy Wielkiej Emigracji',
   'Tekst (autorski, na podstawie programu jednego ze stronnictw emigracyjnych z 1836 r.). Upadek powstania był skutkiem tego, że jego przywódcy nie zwrócili się do ludu. Przyszła Polska musi być wolna nie tylko od zaborców, ale i od ucisku społecznego. Ziemia ma należeć do tych, którzy ją uprawiają, bez żadnej opłaty, a wszyscy obywatele powinni być równi wobec prawa.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy tekst wyraża program Hotelu Lambert czy Towarzystwa Demokratycznego Polskiego. Uzasadnij, odwołując się do tekstu.',
     'Towarzystwa Demokratycznego Polskiego — autor żąda uwłaszczenia chłopów bez odszkodowania i równości wszystkich obywateli, a klęskę powstania tłumaczy brakiem udziału ludu.',
     'TDP (manifest z Poitiers, 1836) = uwłaszczenie bez odszkodowania, równość, powstanie ludowe. Hotel Lambert = monarchia konstytucyjna, liczenie na dyplomację mocarstw, ostrożność w sprawie chłopskiej.'),
   T('abcd', 1, 'Dokończ zdanie. Obozem konserwatywnym Wielkiej Emigracji, skupionym w Hotelu Lambert, kierował\nA. Joachim Lelewel.\nB. Adam Jerzy Czartoryski.\nC. Ludwik Mierosławski.\nD. Adam Mickiewicz.',
     'B',
     'Wszyscy czterej działali na emigracji. Lelewel stał na czele radykalnego Komitetu Narodowego Polskiego, Mierosławski był wojskowym związanym z demokratami, Mickiewicz — poetą i twórcą Legionu we Włoszech (1848).')),

 B('Kraków w 1846 r.',
   'Tekst (autorski). W lutym 1846 r. w Krakowie powołano Rząd Narodowy, który ogłosił zniesienie pańszczyzny i równość wszystkich obywateli. Powstanie upadło po kilku dniach, a w zachodniej Galicji chłopi wymordowali kilkuset szlachciców i urzędników dworskich. Pod koniec roku władze państw zaborczych podjęły decyzję o losie miasta.',
   T('abcd', 1, 'Dokończ zdanie. Na mocy decyzji zaborców Rzeczpospolita Krakowska w 1846 r. została\nA. przyłączona do Królestwa Polskiego.\nB. włączona do Austrii.\nC. podzielona między Austrię i Prusy.\nD. przekształcona w księstwo pod protektoratem Rosji.',
     'B',
     'Wolne Miasto Kraków (utworzone w 1815 r. na kongresie wiedeńskim) wcielono do Austrii w listopadzie 1846 r. jako Wielkie Księstwo Krakowskie.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy wydarzenia w zachodniej Galicji opisane w tekście sprzyjały powstaniu krakowskiemu. Uzasadnij.',
     'Nie — rabacja galicyjska skierowała chłopów przeciwko szlachcie, która organizowała powstanie; władze austriackie wykorzystały konflikt społeczny do stłumienia ruchu narodowego.',
     'Rabacja to dowód, że bez rozwiązania sprawy chłopskiej powstanie nie miało oparcia w ludzie. Ten wniosek przyda się też w wypracowaniach o przyczynach klęsk powstań.')),

 B('Rusyfikacja w Królestwie Polskim',
   'Tekst (autorski). Po upadku powstania styczniowego Królestwo Polskie straciło resztki odrębności. Wprowadzono nazwę „Kraj Przywiślański”, rosyjski stał się językiem urzędów i szkół, a uczniowie mieli zakaz rozmawiania po polsku nawet na przerwach. Szczególnie surowo rusyfikację szkół prowadził kurator warszawskiego okręgu naukowego w latach 1879–1897.',
   T('abcd', 1, 'Dokończ zdanie. Kuratorem warszawskiego okręgu naukowego, o którym mowa w tekście, był\nA. Aleksander Apuchtin.\nB. Józef Hurko.\nC. Michaił Murawjow.\nD. Fiodor Berg.',
     'A',
     'Hurko był generał-gubernatorem warszawskim (1883–1894), Murawjow („Wieszatiel”) tłumił powstanie na Litwie, a Berg był namiestnikiem Królestwa po 1863 r. Wszyscy to symbole represji — rozróżnij ich po funkcji.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Po 1864 r. zlikwidowano odrębność administracyjną Królestwa Polskiego.\n2. Odpowiedzią społeczeństwa na rusyfikację było m.in. tajne nauczanie.\n3. Uniwersytet Warszawski po 1869 r. prowadził zajęcia po polsku.',
     '1 – P, 2 – P, 3 – F.',
     'W 1869 r. Szkołę Główną zastąpiono rosyjskim Cesarskim Uniwersytetem Warszawskim — wykłady odbywały się po rosyjsku.')),

 B('Galicja w czasie autonomii',
   'Tekst (autorski). Po 1867 r. Galicja uzyskała szeroką autonomię. Działał Sejm Krajowy we Lwowie, językiem urzędowym w administracji i szkołach stał się polski, a uniwersytety w Krakowie i Lwowie prowadziły zajęcia po polsku. Jednocześnie kraj był najbiedniejszą częścią monarchii, z której wyjeżdżały za ocean setki tysięcy ludzi.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy w świetle tekstu Galicja była w drugiej połowie XIX w. najlepiej rozwiniętym gospodarczo zaborem. Uzasadnij.',
     'Nie — tekst podkreśla, że była najbiedniejszą częścią monarchii i wyróżniała się masową emigracją zarobkową. Galicja miała najlepsze warunki narodowe i polityczne, ale nie gospodarcze.',
     'To klasyczna pułapka: autonomia ≠ dobrobyt. Najlepiej rozwiniętym gospodarczo zaborem był pruski, a przemysłowo — część Królestwa Polskiego (Łódź, Zagłębie). Galicja: autonomia + „nędza galicyjska”.'),
   T('abcd', 1, 'Dokończ zdanie. W 1872 r. w Krakowie powstała\nA. Akademia Umiejętności.\nB. Szkoła Główna.\nC. Polska Macierz Szkolna.\nD. Kasa im. Mianowskiego.',
     'A',
     'Akademia Umiejętności (od 1919 r. Polska Akademia Umiejętności) to symbol autonomii galicyjskiej. Szkoła Główna działała w Warszawie (1862–1869), Polska Macierz Szkolna to rok 1905 (Królestwo), a Kasa im. Mianowskiego — Warszawa 1881.')),

 B('Praca organiczna w zaborze pruskim',
   'Tekst (autorski). Poznański przedsiębiorca zaczynał od małego sklepu z narzędziami. Z czasem zbudował fabrykę maszyn rolniczych, zatrudniał polskich robotników i wspierał polskie organizacje. Uważał, że naród, który nie umie gospodarować, nie odzyska niepodległości.',
   T('abcd', 1, 'Dokończ zdanie. Tekst opisuje\nA. Leopolda Kronenberga.\nB. Hipolita Cegielskiego.\nC. Karola Marcinkowskiego.\nD. Dezyderego Chłapowskiego.',
     'B',
     'Wszyscy to działacze pracy organicznej, ale: Kronenberg — finansista w Królestwie (zabór rosyjski), Marcinkowski — lekarz, twórca Bazaru Poznańskiego i Towarzystwa Pomocy Naukowej, Chłapowski — wzorowy gospodarz ziemski. Fabryka maszyn rolniczych = Cegielski.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego w zaborze pruskim praca organiczna miała szczególne znaczenie dla zachowania polskości.',
     'Państwo pruskie wykupywało polską ziemię (Komisja Kolonizacyjna) i germanizowało szkoły, dlatego silne polskie gospodarstwa, przedsiębiorstwa, spółdzielnie i banki pozwalały Polakom utrzymać ziemię i niezależność ekonomiczną.',
     'Uzasadnienie musi łączyć dwie rzeczy: politykę zaborcy (zagrożenie) i odpowiedź Polaków (narzędzia pracy organicznej).')),

 B('Polskie partie polityczne pod koniec XIX w.',
   'Tekst (autorski, w duchu publicystyki jednej z partii robotniczych). Robotnik polski ma tego samego wroga co robotnik rosyjski i niemiecki — kapitalistę i carat. Hasło odbudowy niepodległej Polski tylko odciąga robotników od prawdziwej walki. Naszym celem jest wspólna rewolucja proletariatu całego imperium.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy tekst wyraża stanowisko PPS czy SDKPiL. Uzasadnij, odwołując się do tekstu.',
     'SDKPiL — autor odrzuca hasło niepodległości Polski jako szkodliwe i stawia na wspólną rewolucję proletariatu całego imperium (internacjonalizm).',
     'PPS (od 1892/1893) łączyła socjalizm z walką o niepodległość. SDKPiL (Róża Luksemburg) uważała niepodległość za błąd i stawiała na rewolucję w całej Rosji. Słowo-klucz: stosunek do niepodległości.'),
   T('abcd', 1, 'Dokończ zdanie. Program, na którym oparto Polską Partię Socjalistyczną, przyjęto w 1892 r. na zjeździe w\nA. Warszawie.\nB. Krakowie.\nC. Paryżu.\nD. Genewie.',
     'C',
     'Zjazd paryski socjalistów (1892) uchwalił program, a partia działała w Królestwie od 1893 r. Szwajcaria (Genewa) była ważnym ośrodkiem emigracji — tam w 1887 r. powstała Liga Polska — dlatego to dobry dystraktor.'),
   T('uporzadkuj', 1, 'Uporządkuj chronologicznie powstanie organizacji.\nA. Liga Narodowa\nB. Stronnictwo Ludowe w Galicji\nC. „Proletariat” (Wielki Proletariat)\nD. Polska Partia Socjalistyczna (program paryski)',
     'C, D, A, B.',
     '„Proletariat”: 1882 → program PPS: 1892 → Liga Narodowa: 1893 → Stronnictwo Ludowe: 1895. Kotwica: trzy ostatnie powstały w odstępach mniej więcej roku — to „wysyp” partii masowych lat 90.')),

 B('Imperializm i rywalizacja mocarstw',
   'Zestawienie (autorskie). A — otwarcie Kanału Sueskiego; B — wojna rosyjsko-japońska; C — wojna burska; D — zjednoczenie Włoch z Rzymem jako stolicą.',
   T('uporzadkuj', 1, 'Uporządkuj wydarzenia A–D chronologicznie.',
     'A, D, C, B.',
     'Kanał Sueski: 1869 → Rzym stolicą Włoch: 1870/1871 → wojna burska: 1899–1902 → wojna rosyjsko-japońska: 1904–1905.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Wojna rosyjsko-japońska zakończyła się zwycięstwem Japonii.\n2. Wojnę burską prowadziła Wielka Brytania z republikami osadników pochodzenia holenderskiego.\n3. Kanał Sueski od początku był własnością Wielkiej Brytanii.',
     '1 – P, 2 – P, 3 – F.',
     'Kanał zbudowała spółka francusko-egipska; Wielka Brytania wykupiła udziały Egiptu dopiero w 1875 r. Klęska Rosji z Japonią przyczyniła się do wybuchu rewolucji 1905 r.')),
]

BANK['sredniowiecze'] = [
 B('Cesarz, który chciał odbudować Rzym',
   'Tekst (autorski). Cesarz panujący w Konstantynopolu w VI w. odzyskał dla cesarstwa Afrykę Północną, Italię i część Hiszpanii. Polecił zebrać i uporządkować całe dotychczasowe prawo rzymskie, a w stolicy wzniósł świątynię, która przez blisko tysiąc lat była największym kościołem chrześcijaństwa.',
   T('abcd', 1, 'Dokończ zdanie. Tekst opisuje cesarza\nA. Konstantyna Wielkiego.\nB. Teodozjusza Wielkiego.\nC. Justyniana I Wielkiego.\nD. Herakliusza.',
     'C',
     'Kodeks (Corpus iuris civilis), Hagia Sophia i rekonkwista Zachodu to Justynian (527–565). Konstantyn założył Konstantynopol (IV w.), Teodozjusz uznał chrześcijaństwo za religię państwową (IV w.), Herakliusz walczył z Persami i Arabami (VII w.).'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego zbiór praw opisany w tekście miał znaczenie dla późniejszej Europy.',
     'Kodyfikacja Justyniana przechowała prawo rzymskie; od XII w. studiowano ją na uniwersytetach (Bolonia) i stała się podstawą prawa cywilnego wielu państw europejskich.',
     'Słowo-klucz: recepcja prawa rzymskiego. Wiele dzisiejszych pojęć prawa cywilnego (własność, umowa, spadek) wywodzi się z tej kodyfikacji.')),

 B('Rozłam w chrześcijaństwie',
   'Tekst (autorski). W 1054 r. legat papieski złożył na ołtarzu Hagii Sophii bullę ekskomunikującą patriarchę Konstantynopola, a patriarcha odpowiedział klątwą na legatów. Spór dotyczył m.in. zwierzchnictwa papieża nad całym Kościołem, chleba używanego do Eucharystii i sformułowania wyznania wiary.',
   T('abcd', 1, 'Dokończ zdanie. Wydarzenie opisane w tekście nazywamy\nA. wielką schizmą zachodnią.\nB. schizmą wschodnią.\nC. sporem o inwestyturę.\nD. herezją ikonoklastów.',
     'B',
     'Schizma wschodnia (1054) podzieliła Kościół na katolicki i prawosławny. Wielka schizma zachodnia (1378–1417) to okres, gdy było dwóch, a potem trzech papieży. Spór o inwestyturę toczył się między papieżem a cesarzem (Canossa 1077). Ikonoklazm to spór o kult obrazów w Bizancjum (VIII–IX w.).'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Jedną z przyczyn rozłamu był spór o władzę papieża nad całym Kościołem.\n2. Patriarchą Konstantynopola w 1054 r. był Michał Cerulariusz.\n3. Wydarzenie z tekstu nastąpiło po pierwszej wyprawie krzyżowej.',
     '1 – P, 2 – P, 3 – F.',
     'Pierwsza krucjata ruszyła w 1096 r., czyli ponad 40 lat po schizmie. Kotwica: 1054 schizma → 1077 Canossa → 1095 wezwanie Urbana II.')),

 B('Podział monarchii Karolingów',
   'Tekst (autorski). Wnukowie Karola Wielkiego po latach walk zawarli w 843 r. układ. Najstarszy otrzymał tytuł cesarski i pas ziem od Morza Północnego po Italię, pozostali dwaj — ziemie na zachodzie i na wschodzie. Z tych części w kolejnych stuleciach wyrosły dwa wielkie państwa Europy.',
   T('abcd', 1, 'Dokończ zdanie. Układ opisany w tekście zawarto w\nA. Akwizgranie.\nB. Wormacji.\nC. Verdun.\nD. Merseburgu.',
     'C',
     'Traktat w Verdun (843). Akwizgran to stolica Karola Wielkiego, Wormacja — konkordat kończący spór o inwestyturę (1122), Merseburg — miejsce, gdzie Mieszko II złożył hołd cesarzowi (1033).'),
   T('podaj', 1, 'Podaj nazwy dwóch państw, które wyrosły z zachodniej i wschodniej części podzielonej monarchii.',
     'Francja (z państwa zachodniofrankijskiego) i Niemcy (z państwa wschodniofrankijskiego).',
     'Część środkowa (Lotaryngia, Italia) szybko się rozpadła — o Lotaryngię (Alzację i Lotaryngię) Francja i Niemcy spierały się aż do XX w.')),

 B('Czwarta krucjata',
   'Tekst (autorski, na podstawie relacji kronikarzy). W 1204 r. rycerze, którzy wyruszyli na wyprawę krzyżową, zdobyli i złupili wielkie chrześcijańskie miasto nad Bosforem. Zrabowano świątynie i relikwie, a na gruzach dawnej władzy założono nowe cesarstwo łacińskie.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy przebieg wyprawy opisanej w tekście był zgodny z pierwotnym celem wypraw krzyżowych. Uzasadnij.',
     'Nie — krucjaty miały odzyskać Ziemię Świętą z rąk muzułmanów i pomóc chrześcijanom Wschodu, a uczestnicy tej wyprawy zdobyli i złupili chrześcijański Konstantynopol.',
     'IV krucjata to przykład, jak cele religijne ustępowały interesom ekonomicznym (rola Wenecji). Jej skutkiem było trwałe osłabienie Bizancjum i pogłębienie rozłamu między Kościołami.'),
   T('abcd', 1, 'Dokończ zdanie. Bitwa pod Hattinem (1187) doprowadziła do\nA. zdobycia Jerozolimy przez krzyżowców.\nB. utraty Jerozolimy przez krzyżowców na rzecz Saladyna.\nC. powstania zakonu templariuszy.\nD. zakończenia ery wypraw krzyżowych.',
     'B',
     'Krzyżowcy zdobyli Jerozolimę w 1099 r. (I krucjata), a stracili ją w 1187 r. po klęsce pod Hattinem — to wywołało III krucjatę. Templariusze powstali ok. 1119 r., a ostatni bastion krzyżowców (Akka) upadł w 1291 r.')),

 B('Kryzys i odbudowa monarchii piastowskiej',
   'Tekst (autorski). W latach trzydziestych XI w. państwo piastowskie przeżyło głęboki kryzys: walki o władzę, bunt ludności i najazd czeski, w czasie którego zniszczono Gniezno i wywieziono relikwie św. Wojciecha. Władca, który odbudował państwo, przeniósł główny ośrodek władzy w inne miejsce i zawarł sojusz z Rusią.',
   T('abcd', 1, 'Dokończ zdanie. Władca opisany w ostatnim zdaniu tekstu przeniósł główny ośrodek władzy do\nA. Płocka.\nB. Krakowa.\nC. Poznania.\nD. Wrocławia.',
     'B',
     'Kazimierz Odnowiciel uczynił Kraków głównym ośrodkiem władzy. Płock był siedzibą Władysława Hermana pod koniec XI w. — dlatego to najbardziej podchwytliwy dystraktor.'),
   T('podaj', 1, 'Podaj imię księcia czeskiego, który dokonał najazdu opisanego w tekście.',
     'Brzetysław I.',
     'Najazd Brzetysława (ok. 1038/1039) zniszczył Wielkopolskę — to jeden z powodów przeniesienia centrum państwa do Małopolski.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Bolesław Chrobry koronował się na króla w 1025 r.\n2. Mieszko II złożył hołd cesarzowi i zrzekł się korony.\n3. Bolesław Śmiały utrzymał tron do śmierci.',
     '1 – P, 2 – P, 3 – F.',
     'Bolesław Śmiały został wygnany po konflikcie z biskupem Stanisławem (1079). Hołd Mieszka II złożono w Merseburgu (1033).')),

 B('Polska dzielnicowa wobec sąsiadów',
   'Tekst (autorski). Książę mazowiecki, nękany najazdami pogańskich Prusów, sprowadził na swoje ziemie zakon rycerski. Nadał mu ziemię chełmińską, licząc, że rycerze obronią Mazowsze. Zakon szybko podbił Prusów i stworzył silne państwo, które z sojusznika stało się zagrożeniem.',
   T('abcd', 1, 'Dokończ zdanie. Księciem, o którym mowa w tekście, był\nA. Leszek Biały.\nB. Konrad Mazowiecki.\nC. Henryk Brodaty.\nD. Bolesław Wstydliwy.',
     'B',
     'Konrad Mazowiecki sprowadził Krzyżaków w 1226 r. Leszek Biały to jego brat (zginął w Gąsawie w 1227 r.), Henryk Brodaty — książę śląski, Bolesław Wstydliwy — książę krakowski (syn Leszka).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy decyzja księcia przyniosła długofalowe korzyści ziemiom polskim. Uzasadnij.',
     'Nie — zakon stworzył silne państwo, które zajęło Pomorze Gdańskie (1308) i przez blisko dwa stulecia walczyło z Polską, odcinając ją od Bałtyku.',
     'W uzasadnieniu warto użyć faktu: rzeź Gdańska i zajęcie Pomorza (1308–1309). Krótkoterminowo obrona Mazowsza się udała — dlatego pytanie dotyczy skutków „długofalowych”.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. W bitwie pod Legnicą (1241) poległ Henryk Pobożny.\n2. Najazdy mongolskie przyspieszyły zjednoczenie ziem polskich już w połowie XIII w.\n3. Po najazdach mongolskich zaczęto masowo lokować miasta i wsie na prawie niemieckim.',
     '1 – P, 2 – F, 3 – P.',
     'Najazdy pogłębiły rozbicie — śmierć Henryka Pobożnego przekreśliła plany Henryków śląskich. Do zjednoczenia doszło dopiero w 1320 r. Kolonizacja na prawie niemieckim przyspieszyła, bo trzeba było odbudować spustoszone ziemie.')),

 B('Droga do korony w 1320 r.',
   'Zestawienie (autorskie). A — bunt wójta Alberta w Krakowie; B — koronacja Przemysła II w Gnieźnie; C — koronacja Wacława II; D — koronacja Władysława Łokietka.',
   T('uporzadkuj', 1, 'Uporządkuj wydarzenia A–D chronologicznie.',
     'B, C, A, D.',
     'Przemysł II: 1295 → Wacław II: 1300 → bunt wójta Alberta: 1311–1312 → Łokietek: 1320 (w Krakowie, nie w Gnieźnie).'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego Władysław Łokietek koronował się w Krakowie, a nie w Gnieźnie.',
     'Kraków był najważniejszym ośrodkiem politycznym i dzielnicą senioralną, a Wielkopolska z Gnieznem była osłabiona sporami; koronacja w stolicy Małopolski podkreślała ciągłość władzy z czasów Kazimierza Odnowiciela.',
     'CKE zwykle uzna każde poprawne merytorycznie uzasadnienie — kluczowe jest wskazanie roli Krakowa jako głównego ośrodka władzy.')),

 B('Polityka Kazimierza Wielkiego',
   'Tekst (autorski). Król zawarł z zakonem krzyżackim wieczysty pokój. Odzyskał dwie dzielnice utracone za panowania ojca, ale zrzekł się Pomorza Gdańskiego, nazywając zakon jego „jałmużnikiem” — co dawało nadzieję na późniejsze upomnienie się o te ziemie.',
   T('abcd', 1, 'Dokończ zdanie. Na mocy pokoju opisanego w tekście (1343) Polska odzyskała\nA. Pomorze Gdańskie i ziemię chełmińską.\nB. Kujawy i ziemię dobrzyńską.\nC. Ziemię michałowską i Warmię.\nD. Mazowsze i Podlasie.',
     'B',
     'Pokój kaliski (1343): Kujawy i ziemia dobrzyńska wracają do Polski, Pomorze Gdańskie i ziemia chełmińska zostają przy zakonie. Pomorze Gdańskie, ziemię chełmińską i Warmię Polska odzyskała dopiero w 1466 r.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Kazimierz Wielki założył Akademię Krakowską w 1364 r.\n2. Za jego panowania spisano statuty wiślicko-piotrkowskie.\n3. Kazimierz Wielki przyłączył do Polski Śląsk.',
     '1 – P, 2 – P, 3 – F.',
     'Kazimierz zrzekł się praw do Śląska (układy w Trenczynie i Wyszehradzie, 1335). Przyłączył natomiast Ruś Halicką.')),

 B('Wojna trzynastoletnia',
   'Tekst (autorski). W 1454 r. przedstawiciele miast i rycerstwa ziem pruskich wypowiedzieli posłuszeństwo zakonowi i poprosili króla polskiego o włączenie ich ziem do Królestwa. Król wydał akt inkorporacji, co oznaczało wojnę z zakonem.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy wydarzenie opisane w tekście było bezpośrednią przyczyną wojny trzynastoletniej. Uzasadnij.',
     'Tak — prośba Związku Pruskiego i akt inkorporacji Prus wydany przez Kazimierza Jagiellończyka (1454) rozpoczęły wojnę z zakonem.',
     'Przyczyny pośrednie: niezadowolenie stanów pruskich z rządów zakonu (podatki, brak udziału we władzy). Przyczyna bezpośrednia: inkorporacja z 1454 r.'),
   T('abcd', 1, 'Dokończ zdanie. Na mocy II pokoju toruńskiego (1466)\nA. zakon krzyżacki przestał istnieć, a Prusy stały się księstwem świeckim.\nB. Polska odzyskała Pomorze Gdańskie, ziemię chełmińską i Warmię.\nC. Polska odzyskała Kujawy i ziemię dobrzyńską.\nD. wielki mistrz złożył hołd lenny w Krakowie na rynku.',
     'B',
     'A i D to rok 1525 (sekularyzacja zakonu i hołd pruski Albrechta Hohenzollerna), C — pokój kaliski 1343. W 1466 r. zakon stał się lennikiem Polski, ale istniał nadal.')),

 B('Jagiellonowie na tronach Europy',
   'Zestawienie (autorskie). Dwaj władcy z dynastii Jagiellonów zginęli w bitwach z Turkami: pierwszy jako król Polski i Węgier w 1444 r., drugi jako król Czech i Węgier w 1526 r.',
   T('abcd', 1, 'Dokończ zdanie. W bitwie pod Mohaczem w 1526 r. zginął\nA. Władysław Warneńczyk.\nB. Ludwik Jagiellończyk.\nC. Władysław Jagiellończyk (król Czech i Węgier).\nD. Jan Olbracht.',
     'B',
     'Warneńczyk zginął pod Warną (1444). Władysław Jagiellończyk, ojciec Ludwika, zmarł w 1516 r. Jan Olbracht przegrał wyprawę mołdawską (1497), ale zmarł w Toruniu (1501).'),
   T('wyjasnij', 1, 'Wyjaśnij, jakie znaczenie dla Europy Środkowej miała klęska pod Mohaczem.',
     'Większość Węgier znalazła się pod panowaniem tureckim, a korony Czech i Węgier przeszły na Habsburgów — Jagiellonowie stracili te trony, a Habsburgowie stali się główną siłą w regionie.',
     'Mohacz to koniec „systemu jagiellońskiego” w Europie Środkowej. Dwa skutki do zapamiętania: Turcy na Węgrzech i Habsburgowie w Pradze i Budzie.')),

 B('Sobór w Konstancji',
   'Tekst (autorski, na podstawie tez Pawła Włodkowica). Niewiernych nie wolno nawracać mieczem ani przemocą, bo wiara musi być dobrowolna. Poganie mają prawo do swoich państw i swojej własności, a odbieranie im ziem pod pozorem nawracania jest niesprawiedliwe.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy poglądy z tekstu wspierały stanowisko zakonu krzyżackiego w sporze z Polską. Uzasadnij.',
     'Nie — zakon uzasadniał swoje podboje nawracaniem pogan, a tekst odrzuca nawracanie siłą i zabieranie pogańskich ziem. Tezy Włodkowica były argumentem strony polskiej.',
     'Paweł Włodkowic, rektor Akademii Krakowskiej, przedstawił te tezy na soborze w Konstancji (1414–1418). To jedno z najstarszych w Europie wystąpień w obronie praw ludów niechrześcijańskich.'),
   T('abcd', 1, 'Dokończ zdanie. Sobór w Konstancji zakończył\nA. schizmę wschodnią.\nB. wielką schizmę zachodnią.\nC. spór o inwestyturę.\nD. wojny husyckie.',
     'B',
     'W Konstancji wybrano jednego papieża (Marcina V), kończąc okres dwóch, a potem trzech papieży. Ten sam sobór skazał na stos Jana Husa (1415) — wojny husyckie dopiero się wtedy zaczynały.')),

 B('Gospodarka średniowiecznej wsi',
   'Tekst (autorski). Od XI w. w Europie Zachodniej coraz powszechniej dzielono pola na trzy części: jedną obsiewano zbożem ozimym, drugą jarym, a trzecia odpoczywała jako ugór. Rozpowszechnił się ciężki pług z odkładnicą i chomąto, dzięki któremu konie mogły ciągnąć większe ciężary.',
   T('podaj', 1, 'Podaj nazwę systemu uprawy opisanego w tekście.', 'Trójpolówka (system trójpolowy).',
     'W dwupolówce połowa ziemi leżała odłogiem; trójpolówka zwiększyła powierzchnię upraw z 1/2 do 2/3.'),
   T('wyjasnij', 1, 'Wyjaśnij, jaki wpływ zmiany opisane w tekście miały na rozwój miast.',
     'Wzrost plonów dał nadwyżki żywności i przyrost ludności — część ludzi mogła odejść z rolnictwa i zająć się rzemiosłem i handlem w miastach, a nadwyżki trafiały na miejskie targi.',
     'To ten sam mechanizm co w rewolucji neolitycznej: nadwyżka → podział pracy → miasta. Warto go rozpoznawać w różnych epokach.')),
]
